ruleContent.content:
@js:
a = result.match(/var encryptedData = "([^"]+)"/)[1]
b = java.base64DecodeToByteArray(a)


key = java.strToBytes("tH1rU6qZ4vU1sK7pN1wO7mX4bY6dQ9gX");

iv = b.slice(0, 16)
bytes = b.slice(16)

h = java.createSymmetricCrypto(
    "aes/cbc/pkcs7padding", 
    key,
	   iv
).decryptStr(bytes)

option = {
  "headers": {
    "user-agent": "Mozilla/5.0 (Linux; Android 10; K) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/116.0.0.0 Mobile Safari/537.36",
    "accept": "image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8",
    "sec-fetch-site": "cross-site",
    "sec-fetch-mode": "no-cors",
    "sec-fetch-dest": "image",
    "referer": "https://ttmh99.com/",
    "accept-encoding": "gzip, deflate, br",
    "accept-language": "zh-CN,zh;q=0.9"
}}


JSON.parse(h).map(x => `<img src="${x},${JSON.stringify(option)}">`).join("\n")

