ruleBookInfo.intro:
.intro@html##(^|[。！？]+[”」）】]?)##$1<br>
@js:
var r=result,u=baseUrl,
add=java.getElement(
	"#add_other_source li");
if(add&&add!=""){
	var a=add.select("li a"),
	v=book.getVariable("custom");
	b=Array.from(a,x=>{
		name=x.text()
		link=x.attr("href")
		arr=[name,link]
		return arr
		});
		zx=`\n这本书,其他数据源的最新章节：
		(可在右上角三点设置书籍变量更改源目录)\n`;
		var sou="",
		h="https://bqg123.net",
		sy=b.join("\n"),def=zx+sy;
	if(a&&b&&v!=""){
		n=Number(v-1);
		curr=`当前选择：${b[n]}\n`;
		java.toast(curr)
		sou+=curr+def;
		w=",{'webView': true}";
		u=h+b[n][1]+w;
		}else sou=def;
	r+=sou;
	}else u;
	book.tocUrl=u;
	//java.log(book.tocUrl)
r;

