@js:
sort=[];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});
	D=org.jsoup.Jsoup.parse(java.ajax("http://wap.shenshuzw.net/sort/"))
	//java.log(D);
	push("全部🏷分类",null,1,1)	
D.select(".content li").forEach(n=>{
	li=n.select("a")
	let url=(`${li.attr("href")}`).replace(/\d{1}\//g,'{{page}}/')
		push(li.text(),url,1,0.25)
		})
	//java.log(JSON.stringify(sort))
JSON.stringify(sort)

