//a[2]/@href<js>
var id = result.match(/(\d+)\/?/)[1];
var iid = parseInt(id/1000);
`https://m.haitangshufang.com/${iid}/${id}/`;
</js>

ruleSearch.coverUrl:
//a[2]/@href<js>
var id = result.match(/(\d+)\/?/)[1];
var iid = parseInt(id/1000);
`https://img.haitangshufang.com/image/${iid}/${id}/${id}s.jpg`;
</js>

